<script setup lang="tsx">
import { ref, computed, onMounted, onBeforeUnmount } from "vue";
import { useRoute } from "vue-router";
import router from "@/router";
import { GetJudgeDataDownload, GetProblemJudge, ParseProblem, PostJudgeData, PostJudgeDataBuy, PostJudgeDataPrice, PostJudgeDataAi, GetJudgeDataAi, PostJudgeDataAiApply } from "@/apis/problem.ts";
import { useCurrentInstance } from "@/util";
import { ShowErrorParamTips, ShowErrorTips, ShowTextTipsError, ShowTextTipsSuccess } from "@/util/tips";
import { useWebStyleStore } from "@/stores/webStyle.ts";
import { ProblemJudgeTask, ProblemView, AiTestdataJobView } from "@/types/problem.ts";
import { GetFileSizeStr } from "@/util/file.ts";
import { HelpCircleIcon } from "tdesign-icons-vue-next";
import { GetSpaceTypeDescription, SpaceType } from "@/apis/judge.ts";
import { useBreakpoint } from "@/composables/useBreakpoint";

let route = useRoute();
const { globalProperties } = useCurrentInstance();

const webStyleStore = useWebStyleStore();
const { isMobile } = useBreakpoint();

const problemKey = ref("");
let problemId = 0;
const problemLoading = ref(false);

const problemData = ref<ProblemView | null>(null);
const problemSpaceType = ref<SpaceType>(SpaceType.Normal);
const hasAuth = ref(false);

let problemJudgeZip = null as File | null;

const fileInput = ref(null as any);
const fileName = ref("");
const isDragging = ref(false);

const isUploading = ref(false);
const isDownloading = ref(false);

const buyDialogVisible = ref(false);
const buyDialogPrice = ref(0);
const buyDialogUserCoin = ref(0);
const isBuying = ref(false);

const priceEditValue = ref(0);
const isSavingPrice = ref(false);

// 模板预览
const templateFiles = ref<{ language: string; content: string }[]>([]);
const expandedTemplate = ref<number | null>(null);

// ===== AI 生成测试数据 =====
const AI_STATUS_NAMES: Record<number, string> = {
  0: "等待开始",
  1: "排队中",
  2: "规划测试点",
  3: "撰写参考代码",
  4: "编译参考代码",
  5: "生成输入数据",
  6: "运行参考代码",
  7: "已完成",
  8: "生成失败",
};

const aiEnabled = ref(false);
const aiHint = ref("");
const aiJobId = ref(0);
const aiJob = ref<AiTestdataJobView | null>(null);
const aiCreating = ref(false);
const aiApplying = ref(false);
const aiApplyDialogVisible = ref(false);
const aiKeep = ref<Record<string, boolean>>({});
let aiTimer = -1 as any;
let aiFetchSeq = 0; // 拉取世代计数：放弃任务/卸载组件时自增，使在途请求的响应作废

const aiStatusName = computed(() => {
  if (!aiJob.value) return "";
  return AI_STATUS_NAMES[aiJob.value.status] ?? "未知";
});

const aiIsRunning = computed(() => {
  return aiJob.value !== null && aiJob.value.status <= 6;
});

const aiIsFinished = computed(() => {
  return aiJob.value !== null && aiJob.value.status === 7 && !aiJob.value.apply_time;
});

const aiProgressPercent = computed(() => {
  if (!aiJob.value || aiJob.value.task_total <= 0) return 0;
  return Math.min(99, Math.floor((aiJob.value.task_current / aiJob.value.task_total) * 100));
});

const aiTasks = computed(() => aiJob.value?.result?.tasks ?? []);

const aiDropKeys = computed(() =>
  aiTasks.value.filter((t) => !aiKeep.value[t.key]).map((t) => t.key)
);

const clearAiTimer = () => {
  if (aiTimer !== -1) {
    clearTimeout(aiTimer);
    aiTimer = -1;
  }
};

// 拉取任务状态，运行中则 3 秒后继续轮询
// aiFetchSeq 为世代计数：放弃任务/卸载组件时自增，使在途请求的过期响应作废
const fetchAiJob = async () => {
  clearAiTimer();
  if (aiJobId.value <= 0) return;
  const seq = ++aiFetchSeq;
  const res = await GetJudgeDataAi(aiJobId.value);
  // 过期响应（任务已被放弃或组件已卸载）直接丢弃，防止复活轮询
  if (seq !== aiFetchSeq) return;
  if (res.code !== 0) {
    // 运行中任务的瞬时错误不应永久中断轮询：静默排下一次；非运行中才提示并停止
    if (aiJob.value && aiJob.value.status <= 6) {
      aiTimer = setTimeout(fetchAiJob, 3000);
      return;
    }
    ShowErrorTips(globalProperties, res.code);
    return;
  }
  aiJob.value = res.data as AiTestdataJobView;
  // 初始化每个测试点的保留状态：accepted 默认保留，失败默认移除
  const keep: Record<string, boolean> = {};
  aiTasks.value.forEach((t) => {
    keep[t.key] = aiKeep.value[t.key] ?? t.status === "accepted";
  });
  aiKeep.value = keep;
  if (aiJob.value.status <= 6) {
    aiTimer = setTimeout(fetchAiJob, 3000);
  }
};

const handleStartAi = async () => {
  aiCreating.value = true;
  try {
    const res = await PostJudgeDataAi(problemId, aiHint.value);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    aiJobId.value = res.data.id;
    ShowTextTipsSuccess(globalProperties, "生成任务已创建");
    await fetchAiJob();
  } finally {
    aiCreating.value = false;
  }
};

const handleApplyAi = () => {
  aiApplyDialogVisible.value = true;
};

const handleConfirmApply = async () => {
  aiApplying.value = true;
  try {
    const res = await PostJudgeDataAiApply(aiJobId.value, aiDropKeys.value);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    aiApplyDialogVisible.value = false;
    ShowTextTipsSuccess(globalProperties, "已应用为官方测试数据");
    aiJob.value = null;
    aiJobId.value = 0;
    await loadProblem();
  } finally {
    aiApplying.value = false;
  }
};

const handleResetAi = () => {
  aiFetchSeq++; // 使在途请求作废，防止过期响应复活已放弃的任务
  clearAiTimer();
  aiJob.value = null;
  aiJobId.value = 0;
  aiKeep.value = {};
};

const aiTaskColumns = computed(() => {
  const cols: any[] = [
    {
      title: "保留",
      colKey: "keep",
      width: 60,
      cell: (_: any, data: any) => {
        return (
          <t-checkbox
            modelValue={aiKeep.value[data.row.key]}
            onChange={(v: boolean) => (aiKeep.value[data.row.key] = v)}
          />
        );
      },
    },
    { title: "测试点", colKey: "key", width: 70 },
    { title: "用途", colKey: "purpose" },
    {
      title: "状态",
      colKey: "status",
      width: 110,
      cell: (_: any, data: any) => {
        const row = data.row;
        if (row.status === "accepted") {
          return <t-tag theme="success" variant="light">通过</t-tag>;
        }
        const reason = row.sandbox_status || row.fail_reason || "失败";
        return <t-tag theme="danger" variant="light">{reason}</t-tag>;
      },
    },
    {
      title: "输入",
      colKey: "in",
      cell: (_: any, data: any) => {
        return <pre class="dida-ai-data-preview">{data.row.in}</pre>;
      },
    },
    {
      title: "输出",
      colKey: "out",
      cell: (_: any, data: any) => {
        return <pre class="dida-ai-data-preview">{data.row.out}</pre>;
      },
    },
  ];
  if (isMobile.value) {
    return cols.filter((c) => c.colKey !== "purpose");
  }
  return cols;
});

onBeforeUnmount(() => {
  aiFetchSeq++; // 使在途请求作废，防止卸载后轮询泄漏
  clearAiTimer();
});

const fullColumns = [
  {
    title: "任务",
    colKey: "key",
  },
  {
    title: "分数",
    colKey: "score",
  },
  {
    title: "输入文件",
    colKey: "inFile",
  },
  {
    title: "输入文件大小",
    colKey: "inFileSize",
    cell: (_: any, data: any) => {
      return GetFileSizeStr(data.row.inFileSize);
    },
  },
  {
    title: "输出文件",
    colKey: "outFile",
  },
  {
    title: "输出文件大小",
    colKey: "outFileSize",
    cell: (_: any, data: any) => {
      return GetFileSizeStr(data.row.outFileSize);
    },
  },
  {
    title: "输出限制",
    colKey: "outLimit",
    cell: (_: any, data: any) => {
      return GetFileSizeStr(data.row.outLimit);
    },
  },
];

const listColumns = computed(() =>
  isMobile.value
    ? fullColumns.filter(
        (c) => c.colKey !== "inFileSize" && c.colKey !== "outFileSize"
      )
    : fullColumns
);

const taskViews = ref([] as any);

const dropZoneStyle = computed(() => ({
  border: "2px dashed #ccc",
  borderRadius: "6px",
  padding: "20px",
  textAlign: "center",
  cursor: "pointer",
  backgroundColor: isDragging.value ? "#f0f9ff" : "#fff",
  transition: "background-color 0.2s ease",
}));

const dropText = computed(() => {
  if (fileName.value) return `已选择：${fileName.value}`;
  return isDragging.value ? "松开文件以上传" : "拖拽判题数据压缩包到这里，或点击选择文件";
});

const handleClickView = () => {
  router.push({
    name: "problem-detail",
    params: {
      problemKey: problemKey.value,
    },
  });
};

const handleClickEdit = () => {
  router.push({
    name: "manage-problem",
    params: {
      problemKey: problemKey.value,
    },
  });
};

const handleClickDownloadFile = async () => {
  isDownloading.value = true;
  try {
    const res = await GetJudgeDataDownload(problemId);
    if (res.code !== 0) {
      if (res.code === 100059) {
        buyDialogPrice.value = res.data.price;
        buyDialogUserCoin.value = res.data.user_coin;
        buyDialogVisible.value = true;
        return;
      }
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    const link = document.createElement("a");
    link.href = res.data;
    link.target = "_blank";
    link.click();
    URL.revokeObjectURL(link.href);
  } finally {
    isDownloading.value = false;
  }
};

const handleBuyConfirm = async () => {
  isBuying.value = true;
  try {
    const res = await PostJudgeDataBuy(problemId);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    ShowTextTipsSuccess(globalProperties, "购买成功");
    buyDialogVisible.value = false;
    const downloadRes = await GetJudgeDataDownload(problemId);
    if (downloadRes.code === 0) {
      const link = document.createElement("a");
      link.href = downloadRes.data;
      link.target = "_blank";
      link.click();
      URL.revokeObjectURL(link.href);
    }
  } finally {
    isBuying.value = false;
  }
};

const handleSavePrice = async () => {
  isSavingPrice.value = true;
  try {
    const res = await PostJudgeDataPrice(problemId, priceEditValue.value);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    ShowTextTipsSuccess(globalProperties, "定价保存成功");
  } finally {
    isSavingPrice.value = false;
  }
};

const handleClickSave = async () => {
  if (!problemJudgeZip) {
    ShowTextTipsError(globalProperties, "请选择压缩包");
    return;
  }

  isUploading.value = true;

  PostJudgeData(problemId, problemJudgeZip)
    .then(async (res) => {
      if (res.code == 0) {
        fileInput.value.value = null;
        problemJudgeZip = null;
        fileName.value = "";
        problemLoading.value = true;

        ShowTextTipsSuccess(globalProperties, "上传成功");

        await loadProblem();
      } else {
        ShowErrorParamTips(globalProperties, res.code, res.data);
      }
    })
    .catch((err) => {
      console.log(err);
      globalProperties.$message.error({
        duration: 3000,
        content: "上传失败",
      });
    })
    .finally(() => {
      isUploading.value = false;
    });
};

const triggerFileInput = () => {
  fileInput.value?.click();
};

const handleFileChange = (event: any) => {
  const file = event.target.files[0];
  if (file) {
    fileName.value = file.name;
    problemJudgeZip = file;
  }
};

const handleDragEnter = () => {
  isDragging.value = true;
};

const handleDragLeave = () => {
  isDragging.value = false;
};

const handleDrop = (event: any) => {
  event.preventDefault();
  event.stopPropagation();

  isDragging.value = false;
  const file = event.dataTransfer.files[0];
  if (file) {
    fileName.value = file.name;

    const dataTransfer = new DataTransfer();
    dataTransfer.items.add(file);
    fileInput.value.files = dataTransfer.files;

    problemJudgeZip = file;
  }
};

const loadProblem = async () => {
  const res = await GetProblemJudge(problemKey.value);
  if (res.code !== 0) {
    ShowErrorTips(globalProperties, res.code);
    await router.push({ name: "problem" });
    return;
  }

  const problem = res.data.problem;
  hasAuth.value = res.data.has_auth;

  aiEnabled.value = res.data.ai_enabled === true;
  // 恢复最近一次 AI 生成任务（进行中继续轮询；已完成展示预览）
  const latestAiJobId = res.data.ai_job_id ?? 0;
  if (latestAiJobId > 0 && aiJobId.value === 0) {
    aiJobId.value = latestAiJobId;
    await fetchAiJob();
  }

  problemId = problem.id;

  problemData.value = ParseProblem(problem, {} as any);
  problemSpaceType.value = problem.space_type ?? SpaceType.Normal;

  webStyleStore.setTitle(problem.title + " - " + webStyleStore.getTitle);

  const judgeJob = res.data.problem.judge_job;

  taskViews.value = [];
  if (judgeJob && judgeJob.tasks) {
    judgeJob.tasks.forEach((judge: ProblemJudgeTask) => {
      taskViews.value.push({
        key: judge.key,
        score: judge.score,
        inFile: judge.in_file,
        inFileSize: judge.in_file_size,
        outFile: judge.out_file,
        outFileSize: judge.out_file_size,
        outLimit: judge.out_limit,
      });
    });
  } else {
    ShowTextTipsError(globalProperties, "评测数据不存在");
  }

  priceEditValue.value = problem.price || 0;

  // 加载模板预览
  templateFiles.value = [];
  if (problem.template) {
    Object.entries(problem.template).forEach(([lang, content]) => {
      templateFiles.value.push({ language: lang, content: content as string });
    });
  }

  problemLoading.value = false;
};

onMounted(async () => {
  if (Array.isArray(route.params.problemKey)) {
    problemKey.value = route.params.problemKey[0];
  } else {
    problemKey.value = route.params.problemKey;
  }
  if (!problemKey.value) {
    ShowTextTipsError(globalProperties, "题目不存在");
    await router.push({ name: "problem" });
    return;
  }

  problemLoading.value = true;
  await loadProblem();
});
</script>

<template>
  <t-loading :loading="problemLoading">
    <t-row>
      <t-col :span="isMobile ? 12 : 7">
        <div style="margin: 10px">
          <div class="dida-edit-container">
            <t-space>
              <t-button @click="handleClickDownloadFile" :loading="isDownloading">下载</t-button>
              <t-button @click="handleClickSave" theme="danger" :loading="isUploading" v-if="hasAuth">上传</t-button>
              <t-button @click="handleClickEdit" theme="warning" v-if="hasAuth">编辑</t-button>
              <t-button @click="handleClickView">查看</t-button>
            </t-space>
          </div>
          <div
            id="drop-zone"
            :style="dropZoneStyle"
            @click="triggerFileInput"
            @dragenter.prevent="handleDragEnter"
            @dragover.prevent
            @dragleave.prevent="handleDragLeave"
            @drop="handleDrop"
            v-if="hasAuth"
          >
            <input ref="fileInput" type="file" style="display: none" @change="handleFileChange" />
            {{ dropText }}
          </div>
          <t-card v-if="hasAuth && aiEnabled" title="AI 生成测试数据" style="margin: 10px">
            <!-- 发起区：无任务时 -->
            <div v-if="!aiJob">
              <p style="font-size: 12px; color: #888; margin: 0 0 8px">
                AI 将阅读题面，规划测试点并撰写参考代码，在沙箱中运行产出标准输出。生成结果需人工确认后才会生效。
              </p>
              <t-space direction="vertical" style="width: 100%">
                <t-textarea
                  v-model="aiHint"
                  placeholder="可选：生成要求，如「覆盖 n=1 与 n=10^5 边界，包含链状数据，生成 12 个测试点」"
                  :autosize="{ minRows: 2, maxRows: 4 }"
                />
                <t-button theme="primary" @click="handleStartAi" :loading="aiCreating">开始生成</t-button>
              </t-space>
            </div>

            <!-- 进度区：任务进行中 -->
            <div v-else-if="aiIsRunning">
              <t-space direction="vertical" style="width: 100%">
                <div>
                  <t-tag theme="primary" variant="light">{{ aiStatusName }}</t-tag>
                  <span style="margin-left: 8px; font-size: 12px; color: #888">
                    {{ aiJob?.stage_message }}
                  </span>
                </div>
                <t-progress
                  v-if="(aiJob?.task_total ?? 0) > 0"
                  :percentage="aiProgressPercent"
                  status="active"
                />
              </t-space>
            </div>

            <!-- 失败区 -->
            <div v-else-if="aiJob?.status === 8">
              <t-alert theme="error" :message="'生成失败：' + (aiJob?.stage_message ?? '')" />
              <t-button theme="default" @click="handleResetAi" style="margin-top: 8px">重新发起</t-button>
            </div>

            <!-- 预览区：已完成待应用 -->
            <div v-else-if="aiIsFinished">
              <t-space direction="vertical" style="width: 100%">
                <t-collapse>
                  <t-collapse-panel header="参考代码（AI 撰写，编译通过）">
                    <pre class="dida-template-content">{{ aiJob?.result?.reference_code }}</pre>
                  </t-collapse-panel>
                  <t-collapse-panel v-if="aiJob?.result?.compile_message" header="编译信息">
                    <pre class="dida-template-content">{{ aiJob?.result?.compile_message }}</pre>
                  </t-collapse-panel>
                </t-collapse>

                <t-table
                  :data="aiTasks"
                  :columns="aiTaskColumns"
                  row-key="key"
                  vertical-align="top"
                  table-layout="auto"
                />

                <t-space>
                  <t-button theme="primary" @click="handleApplyAi">
                    应用为官方测试数据（保留 {{ aiTasks.length - aiDropKeys.length }} / {{ aiTasks.length }} 个测试点）
                  </t-button>
                  <t-button theme="default" @click="handleResetAi">放弃并重新生成</t-button>
                </t-space>
              </t-space>
            </div>

            <!-- 已应用 -->
            <div v-else-if="aiJob?.apply_time">
              <t-alert theme="success" message="该生成结果已应用为官方测试数据" />
              <t-button theme="default" @click="handleResetAi" style="margin-top: 8px">发起新的生成</t-button>
            </div>
          </t-card>
          <t-table
            :data="taskViews"
            :columns="listColumns"
            row-key="id"
            vertical-align="top"
            table-layout="auto"
            :hover="true"
            style="margin: 10px"
          />
          <t-card
            v-if="templateFiles.length > 0"
            title="模板预览"
            style="margin: 10px"
          >
            <p style="font-size: 12px; color: #888; margin-bottom: 8px">
              本题检测到模板文件（{{ templateFiles.length }} 个语言）。用户在 ProblemDetail
              页加载该题时，编辑器会自动写入模板，并锁定 @EDIT{} 占位标记之外的区域。
            </p>
            <t-collapse
              v-for="(item, idx) in templateFiles"
              :key="item.language"
              :value="expandedTemplate === idx ? [idx] : []"
              @change="(v: any) => (expandedTemplate = (v as number[]).includes(idx) ? idx : null)"
            >
              <t-collapse-panel :header="`${item.language} (template.${item.language === 'cpp' ? 'cpp' : item.language === 'golang' ? 'go' : item.language === 'python' ? 'py' : item.language})`">
                <pre class="dida-template-content">{{ item.content }}</pre>
              </t-collapse-panel>
            </t-collapse>
          </t-card>
        </div>
      </t-col>
      <t-col :span="isMobile ? 12 : 5">
        <div style="margin: 12px">
          <t-descriptions layout="vertical" :bordered="true">
            <t-descriptions-item label="标题">{{ problemData?.title }}</t-descriptions-item>
            <t-descriptions-item label="创建时间">{{ problemData?.insertTime }}</t-descriptions-item>
            <t-descriptions-item label="编辑时间">{{ problemData?.modifyTime }}</t-descriptions-item>
            <t-descriptions-item label="判题方式">{{ problemData?.judgeType }}</t-descriptions-item>
            <t-descriptions-item label="空白字符">{{ problemData?.spaceType }}<t-tooltip :content="GetSpaceTypeDescription(problemSpaceType)"><HelpCircleIcon size="16px" style="color: #888; margin-left: 4px; vertical-align: middle; cursor: help" /></t-tooltip></t-descriptions-item>
            <t-descriptions-item label="评测数据">{{ problemData?.judgeMd5 }}</t-descriptions-item>
            <t-descriptions-item label="上传用户">{{ problemData?.inserterNickname }}</t-descriptions-item>
          </t-descriptions>
          <t-card title="定价设置" v-if="hasAuth" style="margin-top: 12px">
            <t-space direction="vertical" style="width: 100%">
              <t-input-number v-model="priceEditValue" theme="column" placeholder="请输入价格" />
              <div style="font-size: 12px; color: #888">
                <div>-1: 不可购买</div>
                <div>0: 免费购买</div>
                <div>&gt;0: 对应金币价格</div>
              </div>
              <t-button theme="primary" @click="handleSavePrice" :loading="isSavingPrice" style="width: 100%">保存定价</t-button>
            </t-space>
          </t-card>
        </div>
      </t-col>
    </t-row>
  </t-loading>

  <t-dialog
    v-model:visible="buyDialogVisible"
    header="兑换测试数据"
    :confirm-btn="{ content: '确认兑换', loading: isBuying }"
    @confirm="handleBuyConfirm"
  >
    <div>
      <p>兑换后本题永久可下载，不受后续调价影响。</p>
      <t-descriptions :column="1" bordered>
        <t-descriptions-item label="所需金币">{{ buyDialogPrice === 0 ? '免费' : buyDialogPrice }}</t-descriptions-item>
        <t-descriptions-item label="您的金币">{{ buyDialogUserCoin }}</t-descriptions-item>
        <t-descriptions-item label="兑换后剩余">{{ buyDialogUserCoin - buyDialogPrice }}</t-descriptions-item>
      </t-descriptions>
